#!/bin/bash
# DIE-KV-39-SD-V2 KV-022 V2: strict bind of plan_sd39c (event28b + sd39 delta: explicit 6 clock taps, x6 PHY footprint,
# 12 local reset sites off the macro, collector tree regenerated by mk_sd36) with recipe eB3b + sidecar_sd39 ->
# kit-rtl + PHY specialize -> gen.py phys -> kit_preflight -> run_kit place -> declared CDC (DIE-KV-38 form) -> run_kit cts
# (FF structural hold gate).  STAGE=bind|kits|place|cts (default all).
set -uo pipefail
D=/srv/opentallas-scratch2/claude/die-kv-39-1029/sdv2; B=/srv/opentallas-scratch2/claude/die-kv-37-1029/bindroot37
WT=/srv/opentallas-scratch2/claude/wt/die-kv-39-sdv2; PL=$B/kv39/plan_sd39c.json; SC=$B/kv39/sidecar_sd39.json; A=$D/recipe_sd39.json
R=$D/bind; CDC=$D/kv38_cdc_fdi.sdc; ST=${STAGE:-all}
mkdir -p $R $D/kitrtl $D/kits $D/logs; cd $D
python3 - <<PY
import json; d=json.load(open("/srv/opentallas-scratch2/claude/die-kv-37-1029/recipe_kv27f_eB3b.json"))
d["clock_landing_table"]="kv39/sidecar_sd39.json"; d["note"]="DIE-KV-39 V2 sd39: eB3b recipe + sidecar_sd39 (mk_sd36 collector on the sd39 plan) | "+d["note"]
json.dump(d,open("$A","w"),indent=1)
PY
if [ $ST = all ] || [ $ST = bind ]; then
  for f in asbuilt.json asbuilt.yosys.log asbuilt.ys asbuilt_lib_stubs.sv asbuilt_sources.json die_bound_native_mission_lc.v elab.log; do cp /srv/opentallas-scratch2/claude/die-kv-35-1029/bindOld/$f $R/; done
  cd $B; /usr/bin/time -v python3 tools/die_plan/bind.py bind $PL --out $R --asbuilt $A --strict > $R/bind.log 2> $R/bind.time; echo "SD39 BIND_RC $? $(date)"; tail -n 2 $R/bind.log
  for T in kv3_sys_SD kv3_sys_SD_v1; do
    python3 tools/die_plan/bind.py kit-rtl $PL --out $R --asbuilt $A --type $T --kit $D/kitrtl/$T > $D/logs/kitrtl_$T.log 2>&1; echo "SD39 $T KITRTL_RC $?"
    python3 $WT/tools/die_plan/specialize_serdes_phy.py $D/kitrtl/$T $WT/results/kv_serdes_pg_event33 > $D/logs/spec_$T.json 2>&1; echo "SD39 $T SPEC_RC $?"
    grep -c "clk_t5" $D/kitrtl/$T/*_bound.sv | head -2
  done; cd $D
fi
if [ $ST = all ] || [ $ST = kits ]; then
  for T in kv3_sys_SD kv3_sys_SD_v1; do
    python3 $WT/tools/die_plan/gen.py phys $B/kv39/kitplan_sd39.json --out kits --rtl-root $WT --types $T --kit-rtl $T=$D/kitrtl/$T/kit_rtl.f --hold-ff-margin 10 --clock-landing $SC > logs/$T.gen.log 2>&1; echo "SD39 $T GEN_RC $? $(tail -1 logs/$T.gen.log)"
    python3 -I kits/$T/kit_preflight.py kits/$T --plan-dir $B/kv39 --out kits/$T/kit_preflight_sd39.json > logs/$T.preflight.log 2>&1; echo "SD39 $T PREFLIGHT_RC $? $(tail -1 logs/$T.preflight.log)"
    grep -n "OT_TAP\|clk_t" kits/$T/pre_cts.tcl | head -3; grep -c "clk_t5" kits/$T/constraint.sdc
  done
fi
if [ $ST = all ] || [ $ST = place ]; then
  for T in kv3_sys_SD kv3_sys_SD_v1; do ( bash kits/run_kit.sh kits/$T place 32 16; echo "SD39 $T PLACE_RC $? $(date)" ) & done; wait
fi
if [ $ST = all ] || [ $ST = cts ]; then
  for T in kv3_sys_SD kv3_sys_SD_v1; do
    S=$(ls kits/$T/run/results/asap7/*/base/3_place.sdc | head -1); [ -f $S.orig ] || cp $S $S.orig
    grep -q OT_CDC_FDI $S || cat $CDC >> $S
    ( bash kits/run_kit.sh kits/$T cts 32 16; echo "SD39 $T CTS_RC $? $(date)"; tail -3 kits/$T/hold_gate.log ) &
  done; wait
fi
echo "SD39 DONE $(date)"
